import{_ as l,H as a,f as i,i as t}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"11 | 元数据管理与数据分层：让数据资产从混沌到有序","description":"","frontmatter":{},"headers":[{"level":2,"title":"元数据：数据的数据","slug":"元数据-数据的数据","link":"#元数据-数据的数据","children":[{"level":3,"title":"元数据的分类","slug":"元数据的分类","link":"#元数据的分类","children":[]},{"level":3,"title":"元数据管理的挑战","slug":"元数据管理的挑战","link":"#元数据管理的挑战","children":[]},{"level":3,"title":"元数据管理的最佳实践","slug":"元数据管理的最佳实践","link":"#元数据管理的最佳实践","children":[]}]},{"level":2,"title":"元数据管理：数据治理的基石","slug":"元数据管理-数据治理的基石","link":"#元数据管理-数据治理的基石","children":[{"level":3,"title":"从“数据孤岛”到“数据资产”","slug":"从-数据孤岛-到-数据资产","link":"#从-数据孤岛-到-数据资产","children":[]},{"level":3,"title":"保障数据质量的前提","slug":"保障数据质量的前提","link":"#保障数据质量的前提","children":[]},{"level":3,"title":"实现数据血缘追踪","slug":"实现数据血缘追踪","link":"#实现数据血缘追踪","children":[]},{"level":3,"title":"支撑数据合规与安全","slug":"支撑数据合规与安全","link":"#支撑数据合规与安全","children":[]},{"level":3,"title":"提升协作效率","slug":"提升协作效率","link":"#提升协作效率","children":[]},{"level":3,"title":"案例：引入指标平台","slug":"案例-引入指标平台","link":"#案例-引入指标平台","children":[]}]},{"level":2,"title":"数据分层：构建有序的数据体系","slug":"数据分层-构建有序的数据体系","link":"#数据分层-构建有序的数据体系","children":[{"level":3,"title":"为什么需要数据分层","slug":"为什么需要数据分层","link":"#为什么需要数据分层","children":[]},{"level":3,"title":"经典的数据分层模型","slug":"经典的数据分层模型","link":"#经典的数据分层模型","children":[]},{"level":3,"title":"数据分层的设计原则","slug":"数据分层的设计原则","link":"#数据分层的设计原则","children":[]},{"level":3,"title":"案例：百度用户数据平台的分层设计","slug":"案例-百度用户数据平台的分层设计","link":"#案例-百度用户数据平台的分层设计","children":[]}]},{"level":2,"title":"课程总结","slug":"课程总结","link":"#课程总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"大数据应用实战/11｜元数据管理与数据分层：让数据资产从混沌到有序.md","filePath":"大数据应用实战/11｜元数据管理与数据分层：让数据资产从混沌到有序.md","lastUpdated":1795555553000}'),p={name:"大数据应用实战/11｜元数据管理与数据分层：让数据资产从混沌到有序.md"};function r(n,e,h,s,o,u){return a(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="_11-元数据管理与数据分层-让数据资产从混沌到有序" tabindex="-1">11 | 元数据管理与数据分层：让数据资产从混沌到有序 <a class="header-anchor" href="#_11-元数据管理与数据分层-让数据资产从混沌到有序" aria-label="Permalink to &quot;11 | 元数据管理与数据分层：让数据资产从混沌到有序&quot;">​</a></h1><p>你好，我是曹犟。</p><p>在上一节课中，我们从数据治理的视角探讨了数据仓库、数据湖和湖仓一体的选择问题。而无论选择哪种数据治理的架构，要想让数据真正成为企业的资产，都离不开两个核心要素：元数据管理和数据分层。</p><p>今天这节课，我们就来深入讨论如何通过元数据管理和数据分层，让企业的数据资产从混沌走向有序。这两个概念虽然听起来比较抽象，但它们是数据治理中最基础也是最重要的工作。</p><p>我用一个比喻来形容元数据管理和数据分层的重要性：如果把企业的数据比作一座图书馆，那么元数据就是图书的索引卡片，数据分层就是图书的分类系统。没有索引和分类，再多的藏书也只是一堆废纸。</p><h2 id="元数据-数据的数据" tabindex="-1">元数据：数据的数据 <a class="header-anchor" href="#元数据-数据的数据" aria-label="Permalink to &quot;元数据：数据的数据&quot;">​</a></h2><p>我们先从元数据说起。什么是元数据？</p><p>简单来说，元数据就是描述数据的数据。假设你有一张用户订单表，表里存储的是用户的购买记录，每一行对应用户的一次购买行为，这就是数据。而表叫什么名字、有哪些字段、每个字段的类型是什么、字段的取值有什么限定范围、表中数据从哪里来、经过了哪些清洗、多久更新一次、谁有权限使用这种表、谁正在使用这张表，就是这张表的元数据。</p><h3 id="元数据的分类" tabindex="-1">元数据的分类 <a class="header-anchor" href="#元数据的分类" aria-label="Permalink to &quot;元数据的分类&quot;">​</a></h3><p>在实际的大数据系统中，元数据通常包括三个层面的信息。</p><p>技术元数据，代表数据的技术特征。包括表结构、字段类型、分区信息、存储位置、文件格式、压缩方式等。这些信息主要服务于系统和开发人员，保证数据能被正确地存储和访问。</p><p>业务元数据，用来描述数据的业务含义。包括数据的业务定义、计算逻辑、指标口径、数据质量标准、数据负责人、数据的访问权限等。这些信息能够帮助业务人员理解和使用数据。例如，“活跃用户”这个指标，不同部门可能有不同的定义，需要在业务元数据中明确说明；一个特定的表格，每一个行、列，可以被哪些角色查看、写入和删除，这些权限信息也是重要的元数据。</p><p>操作元数据，也就是数据的操作历史。包括数据的创建时间、最后修改时间、访问频率、数据血缘、资源消耗等。这些信息用于监控数据的使用情况和追踪数据问题，通过这些操作元数据，我们能快速定位热门数据、发现性能瓶颈、排查数据问题。</p><p>例如，某张用户行为表每天凌晨 2 点更新，最近 30 天被查询了 1500 次，其中 30% 的查询量来自推荐系统团队，这些查询占用了 80% 的 CPU 资源；某个营销活动效果表依赖于 5 张上游表，当上游的用户标签表延迟更新时，这张表也会相应延迟，这种依赖关系就是数据血缘的体现。</p><h3 id="元数据管理的挑战" tabindex="-1">元数据管理的挑战 <a class="header-anchor" href="#元数据管理的挑战" aria-label="Permalink to &quot;元数据管理的挑战&quot;">​</a></h3><p>元数据管理看似简单，但在实践中面临诸多挑战。</p><p>首先是元数据的收集问题。在一个大型数据系统中，数据源多种多样，有关系型数据库、NoSQL 数据库、文件系统、消息队列等。每种数据源的元数据格式都不相同，如何统一收集是一个技术挑战。</p><p>其次是元数据的一致性问题。同一份数据可能在不同系统中有不同的命名和定义。比如用户ID，在 SDK 采集的数据中叫 distinct_id，在业务数据库的订单表中叫 user_id，在做完 ETL和统一建模后的数据仓库中可能叫 uid，在具体的报表应用中又可能显示为“用户编号”。如何保持这些元数据的一致性和关联性，是元数据管理的核心难题。</p><p>第三是元数据的时效性问题。数据系统是动态变化的，表结构会调整，业务逻辑会变更，如何保证元数据能及时反映这些变化，同时也要避免元数据与实际数据脱节，都需要建立完善的更新机制。</p><p>最后是元数据的使用问题。收集了大量元数据后，如何让这些信息真正发挥作用，而不是变成另一个“数据沼泽”，需要在产品设计上下功夫。</p><h3 id="元数据管理的最佳实践" tabindex="-1">元数据管理的最佳实践 <a class="header-anchor" href="#元数据管理的最佳实践" aria-label="Permalink to &quot;元数据管理的最佳实践&quot;">​</a></h3><p>对于上述提到的这些挑战，基于我过去十几年的实践经验，有一些经验值得跟你分享。</p><p>针对收集问题，推荐采用自动化方式进行元数据采集。人工维护元数据是非常不现实的，基本上没有见过能够持续超过三个月的案例。我的经验是，必须通过技术手段自动采集，应该开发各种采集器，能够自动从整个数据平台的不同系统和介质中，自动抽取元数据信息。当然，自动抽取的前提是要建立统一的元数据模型，才能将采集到的元数据映射到这个统一模型中。</p><p>针对一致性问题，在统一的元数据模型的基础上，要建立统一的元数据中心和数据字典。所有的元数据都应该集中管理，提供统一的查询和管理接口。元数据子系统通常是任何一个大数据系统都必不可少的子系统，也会贯穿整个系统和整个数据流。在数据字典中，要建立字段映射表，记录同一个业务实体在不同系统中的不同名称。例如，上面提到的用户 ID 的例子，就需要在元数据中心中维护这样一个映射关系：distinct_id（SDK 采集日志）= user_id（业务库）= uid（数据仓库）= 用户编号（报表），让所有人和所有系统都能理解这是同一个概念。</p><p>针对时效性问题，需要有实时的同步和版本管理的能力。例如，我们可以通过监听数据库的DDL 变更事件，实时捕获表结构的变化，以最快速度对元数据变更进行同步。而建立元数据版本管理机制，详细记录每次变更的时间、内容和影响范围，才能让我们在对数据进行使用时，使用正确版本的元数据。</p><p>针对使用问题，需要进行产品化和场景化。收集元数据并不是目的，使用元数据才是。数据血缘分析、系统故障排查和定位工具、系统资源消耗统计报表等，这些都是非常典型的、需要基于元数据才能实现的应用，也是保持系统持续可用必不可少的工具。同时，元数据也可以直接改善产品的用户体验。</p><p>例如，在下面这个截图中，我们想基于“国家”这个字段进行筛选，系统基于元数据，自动告诉我们可能有哪些候选项，大大提升了产品可用性。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/11/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/11/1.png" alt=""></a></p><p>类似于测试驱动开发，现在，很多组织也都在尝试基于元数据驱动的开发，也就是在开发新的数据流和数据应用时，应该先定义元数据，再进行开发。这样可以确保数据的规范性，也便于后续的维护和管理，是一种可以尝试的实践方案。</p><h2 id="元数据管理-数据治理的基石" tabindex="-1">元数据管理：数据治理的基石 <a class="header-anchor" href="#元数据管理-数据治理的基石" aria-label="Permalink to &quot;元数据管理：数据治理的基石&quot;">​</a></h2><p>那么，为什么元数据和元数据管理这么重要呢？因为元数据管理，本质上是整个数据治理体系的基石。</p><h3 id="从-数据孤岛-到-数据资产" tabindex="-1">从“数据孤岛”到“数据资产” <a class="header-anchor" href="#从-数据孤岛-到-数据资产" aria-label="Permalink to &quot;从“数据孤岛”到“数据资产”&quot;">​</a></h3><p>在没有元数据管理的企业中，数据就像散落在各处的孤岛。我曾经服务过一家典型的互联网金融企业，他们过去几年，积累了超过 3000 张数据表，但已经没有人知道这些表的全貌。分析师需要用某个数据时，要么找不到，要么找到了却不敢用，因为不知道数据的准确含义和质量如何。</p><p>而通过建立完善的元数据体系，数据变得可发现、可理解、可信任。就像给每个数据资产贴上了详细的标签，任何人都能快速找到并正确使用需要的数据。</p><h3 id="保障数据质量的前提" tabindex="-1">保障数据质量的前提 <a class="header-anchor" href="#保障数据质量的前提" aria-label="Permalink to &quot;保障数据质量的前提&quot;">​</a></h3><p>数据质量是数据治理的核心目标之一，而元数据是保障数据质量的前提条件。没有元数据，你甚至无法定义什么是“高质量”的数据。</p><p>举个例子，“用户 ID 不能为空”这个质量规则，如果没有元数据告诉我们哪个字段是用户 ID、它的数据类型是什么、业务含义是什么，这个规则就无法执行。</p><p>通过元数据，我们可以：</p><ul><li><p>定义数据质量标准（哪些字段是必填的、取值范围是什么）</p></li><li><p>自动化数据质量检查（基于元数据生成质量检查规则）</p></li><li><p>追踪质量问题根源（通过血缘关系找到数据质量问题的源头）</p></li></ul><h3 id="实现数据血缘追踪" tabindex="-1">实现数据血缘追踪 <a class="header-anchor" href="#实现数据血缘追踪" aria-label="Permalink to &quot;实现数据血缘追踪&quot;">​</a></h3><p>在复杂的数据处理流程中，一个下游应用可能依赖几十个上游数据源，并且经过多层加工处理。当应用出现问题时，如果没有元数据记录的血缘关系，排查问题就像大海捞针。</p><p>例如，神策的售后团队经常要回答客户的这类问题：一个每天 8 点开始的运营计划为什么没有按时执行？这个运营计划可能依赖于 3 个标签和 2 个分群的计算。标签和分群的计算上又依赖上游 12 个 event 数据的就绪。而这些 event 数据，又依赖 SDK 采集的数据和来自于业务数据库、数据仓库的数据同步任务。如果没有元数据的良好的记录和呈现，这类问题是没有办法解决的。</p><h3 id="支撑数据合规与安全" tabindex="-1">支撑数据合规与安全 <a class="header-anchor" href="#支撑数据合规与安全" aria-label="Permalink to &quot;支撑数据合规与安全&quot;">​</a></h3><p>随着数据安全法、个人信息保护法的实施，数据合规成为企业必须面对的挑战。元数据也在其中扮演着关键角色。</p><ul><li><p>数据分类分级：通过元数据标记哪些是个人信息、哪些是敏感数据。</p></li><li><p>权限管理：基于元数据控制不同角色对数据的访问权限。</p></li><li><p>合规审计：通过操作元数据追踪数据的使用情况，满足审计要求。</p></li></ul><p>在神策，我们服务了很多金融类客户和在海外有业务的客户，而元数据管理平台实现了自动化的数据分类和权限控制，大大降低了合规风险。</p><h3 id="提升协作效率" tabindex="-1">提升协作效率 <a class="header-anchor" href="#提升协作效率" aria-label="Permalink to &quot;提升协作效率&quot;">​</a></h3><p>数据治理不是技术团队的独角戏，需要业务、技术、运营等多方协作。元数据就是各方沟通的“共同语言”。</p><p>以前业务提需求时，经常出现理解偏差。比如业务说要“活跃用户数”，技术理解的是“登录用户数”，结果做出来的报表不符合预期。现在通过元数据平台，业务可以直接查看指标的准确定义，技术也能清楚地了解业务需求，大大减少了沟通成本和返工。</p><p>总的来说，元数据管理不是成本中心，而是价值创造的加速器。越早开始进行元数据管理，收益也就越大。</p><h3 id="案例-引入指标平台" tabindex="-1">案例：引入指标平台 <a class="header-anchor" href="#案例-引入指标平台" aria-label="Permalink to &quot;案例：引入指标平台&quot;">​</a></h3><p>这里我分享一个如何将元数据管理功能产品化的过程。</p><p>神策在过往服务客户的过程中，从最开始服务中小型互联网企业，逐渐演进到服务互联网巨头、大型国有银行、国际知名零售品牌等大型客户。这些客户内部通常都有比较复杂的组织架构，使用神策系统的人员通常也会在几百人规模。</p><p>在服务这些客户的过程中，会有很多独特的问题，其中关于指标口径的问题是一个典型。也就是，如何在公司内部这么多使用者中统一一些关键指标，例如日活、留存、转化的定义。</p><p>在这之前，神策只有概览 / 报表这类功能，不同使用者之间可以分享计算好的概览 / 报表，但是这个粒度是很粗的，没有办法实现组织内部统一的指标语义的定义、管理、分享和维护。也是在服务这些 KA 客户的过程中，我们意识到了这是一个必须解决的问题：如果没有这个功能，不管你的分析模型有多强大，你的查询性能有多强，在复杂的组织中是没有办法真正得到落地应用的。</p><p>也正是有了这个意识，我们专门引入了指标这个定义，作为我们一系列元数据管理功能的重要组成部分。</p><p>引入指标定义后，我们实现了以下几个关键能力：</p><ul><li><p>统一的指标语义管理。每个指标都有明确的业务定义、计算口径、维度信息、更新频率等元数据。</p></li><li><p>指标的权限管理和分享机制。不同部门和角色可以创建和管理自己的指标，同时也可以将指标分享给其他团队使用。</p></li><li><p>指标的复用和组合能力。已经定义好的指标可以直接被引用到各种分析场景中，不需要重复配置。更重要的是，可以基于已有指标进行组合计算，创建新的派生指标。</p></li><li><p>指标的变更追踪和版本管理。当业务规则调整需要修改指标定义时，系统会记录变更历史，并通知所有使用该指标的人员。这样可以避免指标悄无声息地变化导致的分析结果偏差，保证了数据的可信度。</p></li></ul><p>通过指标平台的建设，我们将元数据管理从底层的技术实现提升到了业务层面的产品功能，真正让元数据为业务服务，这也是元数据管理产品化的一个典型案例。</p><h2 id="数据分层-构建有序的数据体系" tabindex="-1">数据分层：构建有序的数据体系 <a class="header-anchor" href="#数据分层-构建有序的数据体系" aria-label="Permalink to &quot;数据分层：构建有序的数据体系&quot;">​</a></h2><p>说完元数据，我们再来看数据治理中的另一个关键问题：数据分层，也就是将数据按照不同的加工程度和使用目的，组织成不同的层次。</p><p>这是数据仓库建设中的核心概念，但是也同样适用于数据湖和湖仓一体架构。</p><h3 id="为什么需要数据分层" tabindex="-1">为什么需要数据分层 <a class="header-anchor" href="#为什么需要数据分层" aria-label="Permalink to &quot;为什么需要数据分层&quot;">​</a></h3><p>没有分层的数据系统会带来很多问题。</p><p>首先是资源冗余严重。如果每个应用都直接从原始数据计算自己需要的结果，会导致大量重复计算和存储。比如“日活跃用户”这个指标，如果 10 个报表都需要，没有分层的话就要计算 10次。</p><p>其次是数据一致性难以保证。不同的开发人员可能对同一个指标有不同的计算方法，导致结果不一致。我在百度时就遇到过这样的情况，某一个部门自己看的报表和给领导看的报表中，“日活跃用户数”由于口径不同相差超过 4%，直接影响了这个部门的绩效评估。</p><p>第三是开发效率低下。每次开发新应用都要从原始数据开始处理，开发周期长，而且容易出错。</p><p>最后是维护成本高。当底层数据发生变化时，所有直接依赖原始数据的应用都需要修改，牵一发而动全身。</p><h3 id="经典的数据分层模型" tabindex="-1">经典的数据分层模型 <a class="header-anchor" href="#经典的数据分层模型" aria-label="Permalink to &quot;经典的数据分层模型&quot;">​</a></h3><p>在业界，最经典的数据分层模型包括以下几层。</p><ul><li><p>ODS 层（Operational Data Store），即操作数据存储层。这一层存储的是从各个业务系统采集来的原始数据，基本保持原貌，只做必要的清洗和标准化。比如统一时间格式、处理空值等。</p></li><li><p>DWD 层（Data Warehouse Detail），即数据仓库明细层。这一层按照预先设计好的数据模型，对 ODS 层的数据进行清洗、规范化和整合，形成规范的明细数据。比如将用户的注册信息、登录日志、购买记录等整合成用户行为明细表。DWD 层与 ODS 层在数据规模上是同一个层级。</p></li><li><p>DWS 层（Data Warehouse Summary），即数据仓库汇总层。这一层对 DWD 层的数据进行轻度汇总，生成常用的统计指标。比如用户的日活跃、周活跃、月活跃等。这一层由于进行了汇总，相比于 DWD 层有数量级上的减少，这一层依然是公共的，为所有应用服务。</p></li><li><p>ADS 层（Application Data Store），即应用数据存储层。这一层面向具体的应用场景，存储直接供应用使用的数据。比如供报表使用的宽表、供推荐系统使用的特征数据等。之前提到的数据集市的概念（可回顾第 10 节课），就是体现在这一层中。</p></li></ul><p>当然，这只是一个基础模型，不同企业会根据自己的需求进行调整。比如有的企业会将 DWD层和 DWS 层统一整合为 DW 层，或者增加 DIM 层（维度层）专门管理维度数据等。</p><h3 id="数据分层的设计原则" tabindex="-1">数据分层的设计原则 <a class="header-anchor" href="#数据分层的设计原则" aria-label="Permalink to &quot;数据分层的设计原则&quot;">​</a></h3><p>在设计数据分层时，有几个重要原则需要遵循。</p><p>第一，高内聚低耦合。同一层的数据应该有相似的特征和用途，不同层之间的依赖应该单向且清晰。上层可以依赖下层，但下层不应该依赖上层。</p><p>第二，追求数据复用性。公共的计算逻辑应该下沉到更底层，避免重复计算。比如用户的基础属性计算应该在 DWD 层完成，而不是在每个 ADS 表中重复计算。</p><p>第三，逐层加工。数据应该逐层加工，每一层只做该层应该做的事情。不要跳层处理，也不要在一层中做过多的事情。</p><p>第四，屏蔽原始数据变化。通过分层设计，上层应用不需要关心底层数据的变化。当原始数据结构发生变化时，只需要修改 ODS 到 DWD 的 ETL 逻辑，上层应用不受影响。</p><p>除此之外，数据分层设计和元数据管理也是有紧密联系，需要密切协作的：</p><ul><li><p>数据分层的设计需要在元数据中体现。每张表属于哪一层、层与层之间的依赖关系、数据的流转路径，这些都是重要的元数据信息。</p></li><li><p>元数据可以驱动数据分层的自动化。通过元数据定义好各层的规范和转换规则，可以自动生成 ETL 代码，减少人工开发的工作量。</p></li></ul><h3 id="案例-百度用户数据平台的分层设计" tabindex="-1">案例：百度用户数据平台的分层设计 <a class="header-anchor" href="#案例-百度用户数据平台的分层设计" aria-label="Permalink to &quot;案例：百度用户数据平台的分层设计&quot;">​</a></h3><p>让我用一个具体的案例来说明数据分层的实践。在百度负责用户数据平台时，我们设计了一个这样的数据分层架构。如下图所示：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/11/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/11/2.png" alt=""></a></p><ul><li><p>原始日志层：存储各个产品的原始日志，包括搜索日志、点击日志、展现日志等。数据量巨大，每天有百亿级别。</p></li><li><p>E-U 模型层：将原始日志通过 ETL，包括必要的 Join 和 Union 后，按照事件宽表模型，形成统一的 Evnet 宽表和 User 表。</p></li><li><p>Event 表中每条记录代表一个用户行为事件，包含用户 ID、时间、事件类型、事件属性等标准字段，每天依然是百亿级别。</p></li><li><p>User 表中包含用户基础信息、用户公共标签等。User 表每一条记录代表着一个用户，由于有匿名用户的问题，所以 User 表整体规模在十亿级别。</p></li><li><p>公共指标层：计算一些可以提取上来的公共的业务指标，如日活、月活、留存率等。这些指标是在各个产品线中可以复用的。</p></li><li><p>应用层：面向具体应用的数据，如给推荐系统的特征表、给不同产品线或者不同主题的特定报表的数据等。</p></li></ul><p>上面的分层设计基本遵循了之前提到的四层模型。按照这个分层设计，数据冗余大大减少，数据一致性问题基本得到了解决。我们也要求新应用不能直接访问原始日志，并且在使用时尽可能使用上层数据，只有上一层数据无法满足需要的时候，才向下访问。</p><h2 id="课程总结" tabindex="-1">课程总结 <a class="header-anchor" href="#课程总结" aria-label="Permalink to &quot;课程总结&quot;">​</a></h2><p>今天这节课，我们深入探讨了元数据管理和数据分层这两个数据治理的核心概念。</p><p>元数据是数据的“说明书”。做好元数据管理，需要建立统一的元数据中心，实现自动化采集，建立数据字典，并坚持元数据驱动的开发模式。</p><p>数据分层是构建有序数据体系的关键，通过有效的数据分层的划分，可以实现数据的规范化管理、提高复用性、保证一致性。在设计分层时，要遵循高内聚低耦合、数据复用、逐层加工、屏蔽变化等原则。</p><p>元数据管理和数据分层相辅相成，共同构成了数据治理的基础。只有做好这两项基础工作，企业的数据资产才能真正从混沌走向有序，发挥应有的价值。</p><p>对于数据开发工程师和数据产品经理，这节课的重点是了解如何通过元数据管理和数据分层技术，让数据资产变得可发现、可理解，质量得到保障，减少不同部门之间的协作成本，更好地满足应用需求。</p><p>对于数据分析师，则需要知道如何使用元数据来帮助自己更好地了解数据现状，知道自己的需求应该在哪一层面得到满足。</p><p>我准备了如下一张图，希望能够帮你更好地复习本节课的内容：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/11/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E5%BA%94%E7%94%A8%E5%AE%9E%E6%88%98/images/11/3.png" alt=""></a></p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ul><li><p>你的公司现在有统一的元数据管理中心吗？在元数据管理上存在哪些挑战？</p></li><li><p>技术元数据可以自动采集，但业务元数据往往需要人工维护。如何激励业务团队持续维护业务元数据？你有什么好的实践经验？</p></li><li><p>数据分层越多，管理越规范，但 ETL 链路也越长，延迟也越大。在实时性要求较高的场景下，你会如何权衡分层设计？是否有其他替代方案？</p></li></ul><p>欢迎在留言区分享你的思考和经验，如果本节课对你有帮助，也欢迎你分享给其他人。下节课，我们将深入探讨数据模型设计，看看如何将业务需求转化为合理的数据结构。</p>',97)])])}const E=l(p,[["render",r]]);export{c as __pageData,E as default};
